#!/usr/bin/env bash
# run.sh -- generated by tools/gen_case.py; do not hand-edit.
# Usage:  ./run.sh            serial
#         NPROC=12 ./run.sh   parallel (decompose / run / reconstruct)
#         ./run.sh --continue restart from latest written time
set -eo pipefail
cd "$(cd "$(dirname "$0")" && pwd)"
# --- OpenFOAM 14 environment (Foundation / openfoam.org) --------------------
source /opt/openfoam14/etc/bashrc
NPROC="${NPROC:-1}"
# OpenMPI's default shared-memory backing directory (/dev/shm) is blocked in
# this sandbox.  Point it to a scratch directory inside the case (fast vader
# shared-memory transport still works) -- otherwise MPI falls back to TCP and
# is ~20x slower than serial.
mkdir -p .mpi_shm
MPIOPTS="--oversubscribe --mca btl vader,self --mca btl_vader_backing_directory $PWD/.mpi_shm"
CONT=""
if [ "${1:-}" = "--continue" ]; then CONT="-startFrom latestTime"; fi

echo "== OpenFOAM ${WM_PROJECT_VERSION}  case: dip2D_hydrostatic_n10  nproc=${NPROC} =="
if [ ! -d constant/polyMesh ]; then
    blockMesh | tee log.blockMesh
    setFields | tee log.setFields
fi
checkMesh | tee log.checkMesh

if [ "$NPROC" -gt 1 ]; then
    decomposePar -force | tee log.decomposePar
    # shellcheck disable=SC2086
    mpirun $MPIOPTS -np "$NPROC" foamRun -parallel $CONT | tee log.foamRun
    reconstructPar | tee log.reconstructPar
else
    foamRun $CONT | tee log.foamRun
fi

# --- record machine-readable metadata for the report ------------------------
python3 - "$PWD" <<'PY'
import json, subprocess, sys, time
from pathlib import Path
case = Path(sys.argv[1])
log = case / "log.foamRun"
meta = {
    "case": "dip2D_hydrostatic_n10",
    "foam_version": "14",
    "git_hash": "uncommitted",
    "cells": 12000,
    "n_per_D": 10,
    "wall_time_s": None,
    "dpdt": None,
}
if log.exists():
    txt = log.read_text(errors="ignore")
    for line in txt.splitlines():
        if "ExecutionTime" in line:
            meta["clock_time_s"] = line.split("ClockTime =")[-1].strip()
if (case / "postProcessing").exists():
    meta["postProcessing"] = True
(case / "meta_run.json").write_text(json.dumps(meta, indent=2))
PY
